import { verifyToken } from "./auth";
import dbsubscription from "../models/dbsubscription";

export const protect = async (req: any, res: any, next: any) => {
  let token = req.headers.authorization?.replace('Bearer ', '');

  // If no auth header, check query params (useful for direct browser links like PDF downloads)
  if (!token && req.query.token) {
    token = req.query.token as string;
  }

  if (!token) {
    return res.status(401).json({ message: 'No token provided' });
  }

try {
    const decoded = verifyToken(token);
    req.user = decoded;

// --- Subscription Logic Check ---
    // We only restrict access for 'admin' roles who belong to a store.
    // Customers or SuperAdmins (if any) might have different rules.
    if ((req.user?.role === 'admin' || req.user?.role === 'staff') && req.user?.store_id) {

      // Define paths that MUST remain accessible even if the subscription is expired
      const allowedPaths = [
        '/subscription/current',
        '/subscription/list',
        '/subscription/activate',

const isAllowed = allowedPaths.some(path => req.originalUrl.includes(path));

      if (!isAllowed) {
        const sub = await dbsubscription.getCurrentSubscription(req.user.store_id);

        // --- Real Life Scenario Logic ---
        // 1. If NO subscription record exists at all, we allow access for now 
        // (assuming they are a new user/store). They will be prompted in UI.
        if (!sub.result) {
          return next();
        }

// 2. If expired, block access immediately
        if (sub.result.computed_status === 'expired') {
          return res.status(403).json({
            error: true,
            subscription_expired: true,
            message: 'Your plan has expired. Please renew your subscription to continue.'
          });
        }
      }
    }

next();
  } catch (error: any) {
    console.error('Auth Middleware Error:', error.message);
    return res.status(401).json({ message: 'Invalid or expired token' });
  }
};


export const isAdmin = (req: any, res: any, next: any) => {
  if (req.user?.role !== 'admin')
    return res.status(403).json({ message: 'Forbidden: Admin access required' });
  next();
};

