async function SendCustomerOtp(data: any): Promise<SignUpResult> {
    let return_data: SignUpResult = {
        error: false,
        message: 'success',
        result: {}
    };

try {
        const { mobile } = data;

        const generated_otp = Math.floor(100000 + Math.random() * 900000).toString();

        // Check if customer already exists
        const existing = await db.select('signup_request', '*', `WHERE mobile = '${mobile}'`) as User[];

if (existing.length > 0) {
            // Already verified customer — just update OTP for re-verification
            await db.update(
                'signup_request',
                { otp: generated_otp },
                `WHERE mobile = '${mobile}'`
            );
        } else {
            // Brand new customer — insert temp record
            await db.insert('signup_request', {
                mobile,
                otp: generated_otp
            });
        }

// Send OTP via SMS
        const smsResult = await sendMessage(mobile, `Your FoodDesk verification OTP is: ${generated_otp}. Valid for 10 minutes.`);

        if (smsResult.error) {
            return_data.error = true;
            return_data.message = 'Failed to send OTP: ' + smsResult.message;
            return return_data;
        }

        return_data.message = 'OTP sent successfully.';
        return_data.result = { mobile };
        return return_data;

} catch (err: any) {
        console.error('SendCustomerOtp Error:', err.message);
        return_data.error = true;
        return_data.message = 'Internal Server Error';
        return return_data;
    }
}

