        const accesstoken = generateAccessToken();
        const userData: any = {
            name: name ?? signupUser.name,
            role: 'customer',
            is_verified: true,
            accesstoken,
        };
        if (email || signupUser.email) {
            userData.email = email ?? signupUser.email;
        } else {
            userData.email = ''; // Fallback to empty string instead of NULL
        }

// 4. Check if user already exists in users table
        const existingUsers = await db.select('users', '*', `WHERE mobile = '${mobile}'`) as User[];

        let userId: number;

if (existingUsers && existingUsers.length > 0) {
            // User exists — update their record
            await db.update('users', userData, `WHERE mobile = '${mobile}'`);
            userId = existingUsers[0].id;
        } else {
            // User not found — insert new record
            const insertResult = await db.insert('users', {
                ...userData,
                mobile,
            });
            userId = insertResult.id ?? insertResult.insertId;
        }

// 5. Sign JWT
        const payload = {
            id: userId,
            name: name ?? signupUser.name,
            mobile,
            role: 'customer',
        };
        const token = signToken(payload);
        const refreshToken = signRefreshToken(payload);

return_data.message = 'Verified successfully.';
        return_data.result = {
            id: userId,
            name: name ?? signupUser.name,
            email: email ?? signupUser.email,
            mobile,
            role: 'customer',
            token,
            refreshToken,
            accesstoken,
        };

        return return_data;

return return_data;

    } catch (err: any) {
        console.error('VerifyCustomer Error:', err.message);
        return_data.error = true;
        return_data.message = 'Internal Server Error';
        return return_data;
    }
}

