            return_data.message = 'Refresh token is required';
            return return_data;
        }

        const decoded: any = verifyRefreshToken(refreshToken);
        if (!decoded) {
            return_data.error = true;
            return_data.message = 'Invalid or expired refresh token';
            return return_data;
        }

// Remove exp and iat from payload to sign new tokens
        const { exp, iat, ...payload } = decoded;

