import { BrowserRouter } from 'react-router-dom';
import { ToastContainer } from 'react-toastify';
import { Toaster } from './components/ui/sonner';
import axios from 'axios';
import { authStorage } from './utils/localStorage';

import { apiEnpoint } from './utils/constant';
import { setTokens, logout } from './store/features/auth/authSlice';

// Setup global axios interceptors
axios.interceptors.request.use((config) => {
  const authData = authStorage.get();
  if (authData?.token) {
    config.headers.Authorization = `Bearer ${authData.token}`;
  }
  return config;
});

axios.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;

// If 401 Unauthorized and not already retrying and not a refresh request
    if (error.response?.status === 401 && !originalRequest._retry && !originalRequest.url?.includes('/user/refresh')) {
      originalRequest._retry = true;
      const authData = authStorage.get();
      const refreshToken = authData?.refreshToken;

if (refreshToken) {
        try {
          const res = await axios.post(`${apiEnpoint}/user/refresh`, { refreshToken });
          if (res.data?.error === false) {
            const { token, refreshToken: newRefreshToken } = res.data.data;

            // Update Redux Store & LocalStorage
            store.dispatch(setTokens({ token, refreshToken: newRefreshToken }));

            // Retry original request with new token

// Retry original request with new token
            originalRequest.headers.Authorization = `Bearer ${token}`;
            return axios(originalRequest);
          }
        } catch (refreshError) {
          console.error("Token refresh failed:", refreshError);
          store.dispatch(logout());
          return Promise.reject(error);
        }
      } else {
        // No refresh token available, force logout
        store.dispatch(logout());
      }
    }

store.dispatch(logout());
      }
    }
    return Promise.reject(error);
  }
);

